transferReject(fn()=>pb_create_transfer($pdo,12,1,$definitions,7));transferReject(fn()=>pb_create_transfer($pdo,11,2,$definitions,7));
$first=pb_create_transfer($pdo,11,1,$definitions,7);$id=(int)$first['id'];
$again=pb_create_transfer($pdo,11,1,$definitions,8);transferAssert((int)$again['id']===$id,'Duplicate clicks return the original transfer.');
