transferAssert($row['created_by']==7 && $snapshot['options']['graphics_material']==='Chrome','Creator and internal print overrides retained.');
transferAssert(!str_contains(json_encode($snapshot),'private_customer'),'Raw customer metadata is not copied.');
transferAssert($snapshot['source_quantity']===3 && $snapshot['category']['modelcode']==='TEST','Source category and order quantity preserved.');
transferAssert($pdo->query('SELECT * FROM order_items ORDER BY id')->fetchAll(PDO::FETCH_ASSOC)===$before,'Transfer leaves orders unchanged.');
$pdo->exec("INSERT INTO product_builder_designs(component_type,name) VALUES('G','ARTLEX')");
transferAssert($row['img_status']===null,'New transfers have no IMG state.');
transferReject(fn()=>pb_transfer_draft($pdo,$id));
transferReject(fn()=>pb_transfer_save_image($pdo,['id'=>$id,'version'=>1,'img_status'=>'invalid'],7));
transferReject(fn()=>pb_transfer_save_folder($pdo,['id'=>$id,'version'=>1,'folder_path'=>'Y:\Images'],7));
