transferAssert($state['img_status']==='skip'&&$state['status']==='dismissed','Skip persists without deleting the source.');
transferReject(fn()=>pb_transfer_draft($pdo,$id));
transferReject(fn()=>pb_transfer_save_image($pdo,['id'=>$id,'version'=>1,'img_status'=>'ready'],7));
$state=pb_transfer_save_image($pdo,['id'=>$id,'version'=>$state['version'],'img_status'=>'gen'],7);
transferReject(fn()=>pb_transfer_draft($pdo,$id));
$state=pb_transfer_save_image($pdo,['id'=>$id,'version'=>$state['version'],'img_status'=>''],7);
transferAssert($state['img_status']===null,'Can clear a preparation decision.');
$state=pb_transfer_save_image($pdo,['id'=>$id,'version'=>$state['version'],'img_status'=>'ready'],7);
transferAssert(pb_transfer_list($pdo,['q'=>'KTM · SX 50 · 2016-2023'])['total']===1,'Category display text is searchable.');
$folderPath='Y:\E-SHOP\_WEB_2025\GRAPHICS KIT\KTM SX';
transferReject(fn()=>pb_transfer_save_folder($pdo,['id'=>$id,'version'=>1,'folder_path'=>$folderPath],7));
transferReject(fn()=>pb_transfer_save_folder($pdo,['id'=>$id,'version'=>$state['version'],'folder_path'=>"Y:\ninvalid"],7));
transferReject(fn()=>pb_transfer_save_folder($pdo,['id'=>$id,'version'=>$state['version'],'folder_path'=>str_repeat('X',2049)],7));
$state=pb_transfer_save_folder($pdo,['id'=>$id,'version'=>$state['version'],'folder_path'=>$folderPath],7);
$draft=pb_transfer_draft($pdo,$id);
transferAssert($draft['folder_path']===$folderPath&&$draft['transfer_version']===(int)$state['version'],'Draft carries the saved folder, including spaces and backslashes.');
transferAssert($draft['modelcode']==='TEST'&&$draft['components'][0]['quantity']===1&&$draft['components'][0]['options']['graphics_number']==='Yes','Draft resolves category and adapts number and component quantity.');
transferAssert($draft['sku']===''&&!isset($draft['recommended_price'])&&!isset($draft['components'][0]['options']['graphics_name'])&&!isset($draft['components'][0]['options']['graphics_printer']),'No source SKU, order price or personalization silently becomes catalogue defaults.');
transferAssert($draft['components'][0]['design_id']!==null,'Exact existing design is matched.');
$invalid=$draft+['transfer_id'=>$id,'request_key'=>bin2hex(random_bytes(16))];transferReject(fn()=>pb_save_product($pdo,$invalid,7));
transferAssert(pb_transfer_get($pdo,$id)['product_id']===null,'Failed product save leaves transfer unlinked.');
$base=$draft+['transfer_id'=>$id,'recommended_price'=>'149.90','request_key'=>bin2hex(random_bytes(16))];
$state=pb_transfer_save_image($pdo,['id'=>$id,'version'=>$state['version'],'img_status'=>'gen'],8);
transferReject(fn()=>pb_save_product($pdo,$base,7));
transferAssert((int)$pdo->query('SELECT COUNT(*) FROM product_builder_products')->fetchColumn()===0,'A stale Ready draft cannot bypass current queue state.');
$state=pb_transfer_save_image($pdo,['id'=>$id,'version'=>$state['version'],'img_status'=>'ready'],7);
transferReject(fn()=>pb_save_product($pdo,$base,7));
$base['transfer_version']=$state['version'];
$product=pb_save_product($pdo,$base,7);$linked=pb_transfer_get($pdo,$id);
