transferAssert($storedImage['img_status']==='Path'&&$storedImage['img_path']===$folderPath,'Product save atomically copies the exact transfer image folder.');
transferReject(fn()=>pb_transfer_save_folder($pdo,['id'=>$id,'version'=>$linked['version'],'folder_path'=>'Y:\Changed'],8));
transferAssert((int)$linked['product_id']===(int)$product['id']&&$linked['status']==='completed','New listing atomically completes the preparation task.');
$second=pb_save_product($pdo,$base,8);
transferReject(fn()=>pb_transfer_save_image($pdo,['id'=>$id,'version'=>$linked['version'],'img_status'=>'gen'],8));
$other=$base;$other['request_key']=bin2hex(random_bytes(16));transferReject(fn()=>pb_save_product($pdo,$other,8));
transferAssert((int)$second['id']===(int)$product['id']&&(int)$pdo->query('SELECT COUNT(*) FROM product_builder_products')->fetchColumn()===1,'Concurrent or repeated preparation cannot create a second product.');
$save=['id'=>$id,'version'=>$linked['version'],'status'=>'completed','purpose'=>'update_images','product_id'=>$product['id'],'folder_path'=>'Y:\E-SHOP\GRAPHICS KIT\KTM SX','work_note'=>'Images added on Web'];
transferReject(fn()=>pb_transfer_save($pdo,array_replace($save,['version'=>1]),7));
transferReject(fn()=>pb_transfer_save($pdo,array_replace($save,['product_id'=>0]),7));
transferReject(fn()=>pb_transfer_save($pdo,array_replace($save,['status'=>'pending','product_id'=>0]),7));
transferReject(fn()=>pb_transfer_save($pdo,array_replace($save,['product_id'=>999]),7));
transferReject(fn()=>pb_transfer_save($pdo,array_replace($save,['folder_path'=>"Y:\ninvalid"]),7));
$done=pb_transfer_save($pdo,$save,7);transferAssert($done['status']==='completed'&&$done['completed_at']&&$done['folder_path']===$save['folder_path'],'Completed work and paths containing spaces survive.');
transferReject(fn()=>pb_transfer_draft($pdo,$id));
transferAssert(pb_transfer_list($pdo,['status'=>'pending'])['total']===0&&pb_transfer_list($pdo,['status'=>'completed','q'=>'ARTLEX'])['total']===1,'Queue filters are applied before pagination.');
$save['version']=$done['version'];$save['status']='pending';$reopened=pb_transfer_save($pdo,$save,7);transferAssert(!$reopened['completed_at'],'Reopening is supported.');
$pdo->exec("UPDATE order_items SET title='Changed later',deleted_at=NOW() WHERE id=11");
transferAssert(pb_transfer_get($pdo,$id)['title']==='ARTLEX G','Source edits and deletion cannot erase the snapshot.');
transferReject(fn()=>pb_create_transfer($pdo,11,1,$definitions,7));
for($i=20;$i<49;$i++)$pdo->prepare("INSERT INTO product_builder_transfers(order_item_id,order_id,order_number,title,source_sku,snapshot_json,work_note) VALUES(?,1,'ORDER-TEST','Graphics','','{}','')")->execute([$i]);
$page=pb_transfer_list($pdo,['page'=>2,'per_page'=>25]);transferAssert($page['total']===30&&count($page['rows'])===5&&$page['pending']===30,'Queue is paginated, not capped.');
$pdo->exec(str_replace('CREATE TABLE IF NOT EXISTS','CREATE TEMPORARY TABLE IF NOT EXISTS',$schema));
transferAssert(pb_transfer_get($pdo,$id)['folder_path']===$save['folder_path'],'Repeat-safe SQL preserves the queue.');
// IMG filters apply before pagination; completed transfers are a distinct bucket.
$insertFilter=$pdo->prepare("INSERT INTO product_builder_transfers(order_item_id,order_id,order_number,title,source_sku,snapshot_json,work_note,img_status,status,product_id) VALUES(?,1,'FILTER-TEST','Filter fixture','','{}','',?,?,?)");
$source=200;
foreach (array_merge(array_fill(0,31,'gen'),array_fill(0,2,'skip'),array_fill(0,3,'ready'),[null]) as $img) $insertFilter->execute([$source++,$img,$img==='skip'?'dismissed':'pending',null]);
$insertFilter->execute([$source++,null,'completed',null]);
$insertFilter->execute([$source++,'ready','completed',$product['id']]);
$insertFilter->execute([$source++,'gen','pending',$product['id']]);
$pdo->exec("DELETE FROM product_builder_transfers WHERE order_number<>'FILTER-TEST'");
$selection=[];
transferAssert(pb_transfer_list($pdo,$selection)['total']===40,'Older clients still see all statuses.');
transferAssert(pb_transfer_list($pdo,$selection+['img_filters'=>''])['total']===0,'All switches off returns no rows.');
transferAssert(pb_transfer_list($pdo,$selection+['img_filters'=>'unset'])['total']===1,'Unassigned excludes completed records without IMG.');
transferAssert(pb_transfer_list($pdo,$selection+['img_filters'=>'ready'])['total']===3,'Ready excludes already created listings.');
transferAssert(pb_transfer_list($pdo,$selection+['img_filters'=>'completed'])['total']===3,'Completed includes legacy links and completed status regardless of IMG.');
transferAssert(pb_transfer_list($pdo,['img_filters'=>'unset,skip,gen,ready'])['total']===37,'Default active selection hides completed and linked transfers.');
transferAssert(pb_transfer_list($pdo,['q'=>'FILTER-TEST','img_filters'=>'unset,skip,gen,ready'])['total']===40,'Search also includes completed transfers hidden from active work.');
transferAssert(pb_transfer_list($pdo,['q'=>$product['sku'],'img_filters'=>'unset,skip,gen,ready'])['total']===2,'Created product SKU finds linked transfers even with the created filter off.');
transferAssert(pb_transfer_list($pdo,['q'=>'FILTER-TEST','img_filters'=>'','per_page'=>25])['total']===3,'Search can find completed work when all active filters are off.');
transferAssert(pb_transfer_list($pdo,$selection+['img_filters'=>'skip,ready'])['total']===5,'Several switches combine with OR.');
transferAssert(pb_transfer_list($pdo,$selection+['img_filters'=>'skip,skip'])['total']===2,'Duplicate filter values do not duplicate records.');
transferAssert(pb_transfer_list($pdo,['q'=>'NO SUCH ORDER','img_filters'=>'gen'])['total']===0,'Search and status filters combine with AND.');
