foreach (['invalid','gen,invalid',[],false] as $filter) transferReject(fn()=>pb_transfer_list($pdo,['img_filters'=>$filter]));
$pdo->exec("UPDATE product_builder_transfers SET img_status='ready' WHERE order_item_id BETWEEN 200 AND 206");
$page=pb_transfer_list($pdo,$selection+['img_filters'=>'gen','page'=>2,'per_page'=>25]);
transferAssert($page['page']===1&&$page['total']===24&&count($page['rows'])===24,'Last-page removal clamps to the remaining page.');

echo "Transfers: snapshots, Graphics-only, duplicate protection, drafts, atomic linkage, stale writes, paths, completion and pagination OK (temporary tables only).\n";
